'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '../..');
const src = fs.readFileSync(path.join(root, 'docs/scifi-ui/scripts/formatx-core-real3d-v20.js'), 'utf8');
const css = fs.readFileSync(path.join(root, 'docs/scifi-ui/styles/formatx-core-real3d-v20.css'), 'utf8');

assert.match(src, /const VERSION = 'v21'/);
assert.match(src, /const VISUAL_REVISION = 'v24-volumetric-crystal'/);
assert.match(src, /fxCoreReal3dRevision = 'ready-v21'/);
assert.match(src, /fxCoreRendererRevision = 'single-webgl2-indexed-3d-v21'/);
assert.match(src, /fxCoreReal3d = 'ready-v20'/);
assert.match(src, /fxCoreRenderer = 'single-webgl2-indexed-3d-v20'/);
assert.equal((src.match(/getContext\('webgl2'/g) || []).length, 1, 'exactly one WebGL2 context required');
assert.match(src, /gl\.enable\(gl\.DEPTH_TEST\)/);
assert.match(src, /gl\.drawElements\(gl\.TRIANGLES/);
assert.match(src, /gl\.drawElements\(gl\.LINES/);
assert.match(src, /function crystalFilamentGeometry\(angularSegments, tubeSides\)/);
assert.match(src, /const filaments = uploadMesh\(crystalFilamentGeometry/);
assert.match(src, /drawMesh\(filaments,base,2,\.72,\.45,time\)/);
assert.doesNotMatch(src, /drawLines\(star,base/, 'flat GL line grid must not be part of the production frame');
assert.match(src, /function referenceRadius\(angle\)/);
assert.match(src, /p = \.68/);
assert.match(src, /return \.025 \+ \.975 \* lp/);
assert.match(src, /radius \* t \* 1\.12 \* flowing/);
assert.match(src, /for \(const ring of \[2, 4, 7, 10, radialSegments\]\)/);
assert.match(src, /angularSegments \/ 16/);
assert.match(src, /float membrane=band\(diamond,\.31,\.018\)/);
assert.match(src, /float reactorRings=band\(radial,\.16,\.013\)/);
assert.match(src, /float axisX=exp\(-abs\(p\.x\)\*22\.0\)/);
assert.match(src, /float axisY=exp\(-abs\(p\.y\)\*18\.0\)/);
assert.match(src, /float violetArc=/);
assert.match(src, /vec3 cyan=vec3\(\.01,\.66,1\.42\)/);
assert.match(src, /vec3 violet=vec3\(\.74,\.045,1\.30\)/);
assert.match(src, /y=mobile\?\.40:\.01/);
assert.match(src, /scaleX=\(mobile\?\.88:1\.14\)\*pulse, scaleY=\(mobile\?\.94:1\.14\)\*pulse/);
assert.match(src, /scaling\(1\.08\*ringPulse/);
assert.match(src, /scaling\(\.82,\.82,\.82\)/);
assert.match(src, /scaling\(\.60,\.60,\.60\)/);
assert.match(src, /scaling\(\.40,\.40,\.40\)/);
assert.match(src, /scaling\(\.20,\.20,\.20\)/);
assert.match(src, /reactorScale=\.052/);
assert.match(src, /function compositeBloom\(\)/);
assert.match(src, /quarter-resolution-separable-bloom-v23/);
assert.match(src, /transpose\(inverse\(mat3\(uModel\)\)\)/);
assert.match(src, /environmentRadiance\(reflect\(incident,normal\)\)/);
assert.match(src, /refract\(incident,normal,\.676\)/);
assert.match(src, /vec3 absorption=exp\(-vec3\(1\.65,\.34,\.095\)\*opticalDepth\)/);
assert.match(src, /gl\.bindFramebuffer\(gl\.FRAMEBUFFER,\s*sceneFramebuffer\)/);
assert.match(src, /gl\.drawArrays\(gl\.TRIANGLES,0,3\)/);
assert.match(src, /concave-pnorm-four-sail-volume-v24/);
assert.match(src, /physical-crystal-ribs-and-caustics-v24/);
assert.match(src, /reference-crystal-portal-v24/);
assert.match(src, /physical-tube-filaments-v24/);
assert.match(src, /film-reactive-v1/);
assert.match(src, /adaptive-60-plus-fps/);
assert.doesNotMatch(src, /addEventListener\(['"](?:wheel|touchmove)['"][\s\S]{0,300}preventDefault/, 'page scroll capture forbidden');
assert.doesNotMatch(src, /scrollTo\s*\(|scrollIntoView\s*\(/, 'renderer must not reposition the page');
assert.doesNotMatch(src, /drawImage\s*\(|new Image\s*\(|background-image/i);
assert.doesNotMatch(src, /THREE\b|three\.js|babylon|gsap/i);
assert.match(css, /pointer-events:\s*none/);
assert.match(css, /100dvh/);

console.log('PASS: v24 uses a volumetric four-sail WebGL2 crystal, physical indexed ribs, refractive glass, four 3D portal rings and mobile-resolution separable bloom.');
